/**
 * Rewrites "magic property" statement patterns into {@link TupleFunctionCall} nodes so that set-returning extension
 * functions ({@link TupleFunction}s registered in the {@link TupleFunctionRegistry}) can be invoked from plain SPARQL:
 *
 * <pre>
 * ?s strf:split ?part .                 # one argument, one result
 * (?s ",") strf:split (?part) .         # RDF collections carry several arguments / results
 * (1 10 3) arrf:generateSeries ?n .
 * </pre>
 *
 * A pattern whose predicate is a constant IRI registered as a tuple function is removed from its basic graph pattern
 * together with the {@code rdf:first}/{@code rdf:rest} patterns of its argument and result collections. The remaining
 * patterns of the group become the left side of a {@link Lateral} whose right side is the tuple function call, so the
 * call is evaluated once per solution of the group with the argument variables bound.
 */
@Experimental
public class TupleFunctionMagicPropertyOptimizer implements QueryOptimizer {

	private final TupleFunctionRegistry registry;

	public TupleFunctionMagicPropertyOptimizer() {
		this(TupleFunctionRegistry.getInstance());
	}

	public TupleFunctionMagicPropertyOptimizer(TupleFunctionRegistry registry) {
		this.registry = registry;
	}

	@Override
	public void optimize(TupleExpr tupleExpr, Dataset dataset, BindingSet bindings) {
		List<StatementPattern> magicPatterns = new ArrayList<>();
		tupleExpr.visit(new AbstractSimpleQueryModelVisitor<RuntimeException>(false) {
			@Override
			public void meet(StatementPattern node) {
				Var predicate = node.getPredicateVar();
				if (predicate != null && predicate.hasValue() && predicate.getValue() instanceof IRI iri
						&& registry.has(iri.stringValue())) {
					magicPatterns.add(node);
				}
			}
		});
		for (StatementPattern pattern : magicPatterns) {
			if (pattern.getParentNode() != null) {
				rewrite(pattern);
			}
		}
	}

	private void rewrite(StatementPattern pattern) {
		List<StatementPattern> group = groupPatterns(pattern);
		List<StatementPattern> consumed = new ArrayList<>();
		List<Var> args = resolveList(pattern.getSubjectVar(), group, consumed);
		List<Var> results = resolveList(pattern.getObjectVar(), group, consumed);

		TupleFunctionCall call = new TupleFunctionCall();
		call.setURI(pattern.getPredicateVar().getValue().stringValue());
		Set<String> inputNames = new LinkedHashSet<>();
		for (Var arg : args) {
			if (arg.hasValue()) {
				call.addArg(new ValueConstant(arg.getValue()));
			} else {
				call.addArg(arg.clone());
				inputNames.add(arg.getName());
			}
		}
		for (Var result : results) {
			call.addResultVar(result.clone());
			inputNames.add(result.getName());
		}

		for (StatementPattern listPattern : consumed) {
			detach(listPattern);
		}
		// the magic pattern's position becomes the call; if it has join siblings, wrap what remains of the group
		pattern.replaceWith(call);
		if (!(call.getParentNode() instanceof Join)) {
			return;
		}
		TupleExpr survivor = detach(call);
		TupleExpr root = groupRoot(survivor);
		Lateral lateral = new Lateral();
		lateral.setRightInputBindingNames(inputNames);
		root.replaceWith(lateral);
		lateral.setLeftArg(root);
		lateral.setRightArg(call);
	}

	/** Walks up through plain joins (stopping at a scope-changing join) to the root of the basic graph pattern. */
	private static TupleExpr groupRoot(TupleExpr node) {
		TupleExpr root = node;
		while (root.getParentNode() instanceof Join parent
				&& !(root instanceof Join join && join.isVariableScopeChange())) {
			root = parent;
		}
		return root;
	}

	private static List<StatementPattern> groupPatterns(StatementPattern pattern) {
		TupleExpr root = groupRoot(pattern);
		List<StatementPattern> patterns = new ArrayList<>();
		collectPatterns(root, patterns, true);
		return patterns;
	}

	private static void collectPatterns(TupleExpr node, List<StatementPattern> patterns, boolean isRoot) {
		if (node instanceof StatementPattern sp) {
			patterns.add(sp);
		} else if (node instanceof Join join && (isRoot || !join.isVariableScopeChange())) {
			collectPatterns(join.getLeftArg(), patterns, false);
			collectPatterns(join.getRightArg(), patterns, false);
		}
	}

	/**
	 * Resolves a subject/object into argument or result terms: a plain term is a single entry, an anonymous variable
	 * heading an {@code rdf:first}/{@code rdf:rest} chain within the group is expanded into its members.
	 */
	private static List<Var> resolveList(Var head, List<StatementPattern> group, List<StatementPattern> consumed) {
		List<Var> items = new ArrayList<>();
		if (head.hasValue() || !head.isAnonymous()) {
			items.add(head);
			return items;
		}
		List<StatementPattern> chain = new ArrayList<>();
		Var current = head;
		while (true) {
			if (current.hasValue()) {
				if (RDF.NIL.equals(current.getValue())) {
					consumed.addAll(chain);
					return items;
				}
				break;
			}
			StatementPattern first = find(group, current, RDF.FIRST);
			StatementPattern rest = find(group, current, RDF.REST);
			if (first == null || rest == null) {
				break;
			}
			chain.add(first);
			chain.add(rest);
			items.add(first.getObjectVar());
			current = rest.getObjectVar();
		}
		// not a well-formed collection: treat the head as a single term
		items.clear();
		items.add(head);
		return items;
	}

	private static StatementPattern find(List<StatementPattern> group, Var subject, IRI predicate) {
		for (StatementPattern sp : group) {
			Var s = sp.getSubjectVar();
			Var p = sp.getPredicateVar();
			if (!s.hasValue() && s.getName().equals(subject.getName()) && p.hasValue()
					&& predicate.equals(p.getValue())) {
				return sp;
			}
		}
		return null;
	}

	/** Removes a join operand, collapsing its parent join onto the sibling, which is returned. */
	private static TupleExpr detach(TupleExpr node) {
		QueryModelNode parent = node.getParentNode();
		if (parent instanceof Join join) {
			TupleExpr sibling = join.getLeftArg() == node ? join.getRightArg() : join.getLeftArg();
			if (join.isVariableScopeChange() && sibling instanceof Join siblingJoin) {
				siblingJoin.setVariableScopeChange(true);
			}
			join.replaceWith(sibling);
			return sibling;
		}
		throw new IllegalStateException("Cannot detach a pattern that is not a join operand: " + node);
	}

	/** Exposes the argument expressions of a call as variables for join planning. */
	public static List<Var> variables(TupleFunctionCall call) {
		List<Var> vars = new ArrayList<>(call.getArgs().size() + call.getResultVars().size());
		for (ValueExpr arg : call.getArgs()) {
			if (arg instanceof Var var) {
				vars.add(var);
			}
		}
		vars.addAll(call.getResultVars());
		return vars;
	}
}
